python3 -c "import flowio, glob, os
import numpy as np

def parse_spill(sp):
    parts = sp.split(',')
    n = int(parts[0])
    detectors = parts[1:n+1]
    vals = [float(x) for x in parts[n+1:] if x]
    mat = np.array(vals).reshape((n, n))
    return detectors, mat

spills = {}
for f in sorted(glob.glob('/task/input/fcs/*.fcs')):
    fo = flowio.FlowData(f)
    dets, mat = parse_spill(fo.text['spillover'])
    fname = os.path.basename(f)
    spills[fname] = mat

for f1 in spills:
    for f2 in spills:
        if f1 < f2:
            diff = np.max(np.abs(spills[f1] - spills[f2]))
            if diff > 1e-5:
                print(f'{f1} vs {f2}: max diff = {diff}')
"

